/* 6. pixel-exact coverage vs an independent exact (BigInt) reference  */
/* ------------------------------------------------------------------ */

(function testExactReference() {
  console.log('\n[6] exact coverage vs BigInt reference (shared edges/vertices)');

  function exactMask(tris, W, H, S) {
    const mask = new Uint8Array(W * H);
    const ONE = S;
    const HALF = S >> 1;
    function od(ax, ay, bx, by, cx, cy) {
      return BigInt(bx - ax) * BigInt(cy - ay) - BigInt(by - ay) * BigInt(cx - ax);
    }
    function topLeft(ax, ay, bx, by) {
      const dx = bx - ax, dy = by - ay;
      return dy < 0 || (dy === 0 && dx > 0);
    }
    for (const t of tris) {
      const P = t.map(v => {
        const iw = 1 / v.w;
        const nx = v.x * iw, ny = v.y * iw;
        const sx = (nx + 1) * 0.5 * W, sy = (1 - ny) * 0.5 * H;
        return { X: Math.round(sx * ONE), Y: Math.round(sy * ONE) };
      });
      const [a, b, c] = P;
      const area = od(a.X, a.Y, b.X, b.Y, c.X, c.Y);
      if (area <= 0n) continue;
      const minX = Math.max(0, Math.floor(Math.min(a.X, b.X, c.X) / ONE));
      const maxX = Math.min(W - 1, Math.ceil(Math.max(a.X, b.X, c.X) / ONE));
      const minY = Math.max(0, Math.floor(Math.min(a.Y, b.Y, c.Y) / ONE));
      const maxY = Math.min(H - 1, Math.ceil(Math.max(a.Y, b.Y, c.Y) / ONE));
      for (let y = minY; y <= maxY; y++) {
        for (let x = minX; x <= maxX; x++) {
          const px = x * ONE + HALF, py = y * ONE + HALF;
          const e0 = od(b.X, b.Y, c.X, c.Y, px, py);
          const e1 = od(c.X, c.Y, a.X, a.Y, px, py);
          const e2 = od(a.X, a.Y, b.X, b.Y, px, py);
          if (e0 < 0n || e1 < 0n || e2 < 0n) continue;
          if (e0 === 0n && !topLeft(b.X, b.Y, c.X, c.Y)) continue;
          if (e1 === 0n && !topLeft(c.X, c.Y, a.X, a.Y)) continue;
          if (e2 === 0n && !topLeft(a.X, a.Y, b.X, b.Y)) continue;
          mask[y * W + x] = 1;
        }
      }
    }
    return mask;
  }

  const S = R.ONE;
  const scenes = [];
  scenes.push(['shared-edge quad', buildGrid(1, -0.9, 0.9, -0.9, 0.9)]);
  {
    const tris = [];
    const K = 7;
    for (let k = 0; k < K; k++) {
      const a0 = 2 * Math.PI * k / K;
      const a1 = 2 * Math.PI * (k + 1) / K;
      const p0 = [Math.cos(a0), Math.sin(a0)];
      const p1 = [Math.cos(a1), Math.sin(a1)];
      tris.push([
        R.makeVertex(0, 0, 0, 1, [0]),
        R.makeVertex(p0[0], p0[1], 0, 1, [0]),
        R.makeVertex(p1[0], p1[1], 0, 1, [0]),
      ]);
    }
    const fixed = tris.map(t => {
      const sx = v => (v.x + 1) * 0.5 * 64;
      const sy = v => (1 - v.y) * 0.5 * 64;
      const a = t[0], b = t[1], c = t[2];
      const area = (sx(b) - sx(a)) * (sy(c) - sy(a)) - (sy(b) - sy(a)) * (sx(c) - sx(a));
      return area > 0 ? t : [t[0], t[2], t[1]];
    });
    scenes.push(['shared-vertex fan', fixed]);
  }
  scenes.push(['grid + guard band', buildGrid(9, -1.7, 1.7, -1.7, 1.7)]);

  for (const [name, tris] of scenes) {
    const W = 48, H = 48;
    const fb = R.render(tris, W, H, 1, { guardBand: 1.05 });
    const ref = exactMask(tris, W, H, S);
    let mismatch = 0;
    for (let i = 0; i < W * H; i++) {
      const a = fb.count[i] > 0 ? 1 : 0;
      if (a !== ref[i]) mismatch++;
    }
    check(`${name}: exact coverage match (${W * H} px)`, mismatch === 0,
      'mismatch=' + mismatch);
  }
})();

console.log(`\n===== ${passCount} passed, ${failCount} failed =====`);
process.exit(failCount ? 1 : 0);
```

### What each section proves

1. **Seamless tiling / top-left rule** — a grid of two-triangle cells over the whole viewport (`N = 4,7,8,16,128`); every pixel must be covered **exactly once**. `N = 128` makes many vertices land exactly on pixel centers, exercising the `e == 0` tie-break.
2. **Guard-band clipping** — the grid spans `[-2,2]²`, viewport `[-1,1]²`, guard band tightened to `G = 1.001, 1.25, 1.5, 3`. The viewport must still tile exactly once, proving clipped shared edges do not crack.
3. **Near-plane clipping** — `z = (0.5 − ndcX)·0.5` cuts the near plane through the grid (both `w = 1` and varying `w`); the visible region tiles exactly once and the clipped region is empty.
4. **Perspective-correct interpolation** — `w = 2,4,3` with attributes equal to camera-space `x`/`y`; every covered pixel is compared to an independent ray/plane ground truth. Required error `< 1e-9` (achieved `≈ 2e-16`).
5. **Z-buffer + culling** — a near front face beats a closer back face and a degenerate triangle; draw order does not matter; back faces/degenerates alone write nothing.
6. **Pixel-exact coverage vs BigInt reference** — a separately written exact-integer coverage implementation is compared mask-for-mask for a shared-edge quad, a shared-vertex fan, and a guard-band-clipped grid.

